import React, { useEffect, useState } from "react";
import "./DisplayFoodTruck.css";

export default function DisplayFoodTruck() {
  const [vendors, setVendors] = useState([]);

  useEffect(() => {
    fetch("http://localhost:8080/getAllVendors")
      .then(res => res.json())
      .then(data => setVendors(data))
      .catch(err => console.error("Error fetching vendors:", err));
  }, []);

  return (
    <div>
      <h2 style={{ textAlign: "center", marginBottom: "20px" }}>Food Truck Vendors</h2>
      <div className="vendor-container">
        {vendors.length > 0 ? (
          vendors.map((vendor, index) => (
            <div key={index} className="vendor-card">
              <p><strong>Cuisine:</strong> {vendor.cuisine || "N/A"}</p>
              <p><strong>Region:</strong> {vendor.region || "N/A"}</p>
              <p><strong>Highlights:</strong> {vendor.highlights || "N/A"}</p>
              <p><strong>Phone:</strong> {vendor.phone || "N/A"}</p>
            </div>
          ))
        ) : (
          <p style={{ textAlign: "center", color: "#888" }}>No vendors found</p>
        )}
      </div>
    </div>
  );
}
